<script setup lang="ts">
import { ui } from "../ui"
import DateTime from '../components/DateTime.vue'
import { ref } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import PageHeading from '../components/PageHeading.vue'
import { api,notify } from '../composables/api'
import { useCollaborationAction } from '../composables/collaboration'
import { useInvestigation } from '../composables/investigation'
import type { DeliveryDetail } from '../types'
const route=useRoute(),router=useRouter(),{data,loading,error,reload}=useInvestigation<DeliveryDetail>(()=>'/deliveries/'+route.params.delivery),perform=useCollaborationAction(),review=ref<{text:string;digest:string}|null>(null),saving=ref(false),actionError=ref('')
async function retry(){saving.value=true;try{await perform('/deliveries/'+route.params.delivery+'/retry','POST',{});notify('A bounded retry cycle was queued with the same logical delivery identity.');await reload()}catch(e){actionError.value=e instanceof Error?e.message:'Retry failed.'}finally{saving.value=false}}
async function preview(){try{review.value=await api('/deliveries/'+route.params.delivery+'/review','POST')}catch(e){actionError.value=e instanceof Error?e.message:'Review unavailable.'}}
async function resend(){if(!review.value)return;saving.value=true;try{const result=await perform<{id:string}>('/deliveries/'+route.params.delivery+'/resend','POST',{preview_digest:review.value.digest});review.value=null;await router.push('/alerts/history/'+result.id)}catch(e){actionError.value=e instanceof Error?e.message:'Resend failed.'}finally{saving.value=false}}
</script>
<template><PageHeading :class="ui('$all', '$PageHeading')" title="Delivery details" subtitle="One logical delivery, its immutable payload and attempt history."><RouterLink to="/alerts/history" :class="ui('$all', '$a', 'button')">Delivery history</RouterLink><button :class="ui('$all', '$button', 'button')" :disabled="loading" @click="reload">Refresh</button></PageHeading><div v-if="error||actionError" :class="ui('$all', '$div', 'notice danger')" role="alert">{{error||actionError}}<button :class="ui('$all', '$button', 'button')" @click="reload">Reload delivery</button></div><p :class="ui('$all', '$p')" v-if="loading" role="status">Loading delivery…</p><template v-if="data"><div :class="ui('$all', '$div', 'panel delivery-summary')"><h2 :class="ui('$all', '$h2')">{{data.delivery.event}} <span :class="ui('$all', '$span', 'status-badge', ('status-'+data.delivery.status))" >{{data.delivery.status}}</span></h2><dl :class="ui('$all', '$dl', 'context-list')"><div :class="ui('$all', '$div')"><dt :class="ui('$all', '$dt')">Logical ID</dt><dd :class="ui('$all', '$dd', 'code')">{{data.delivery.id}}</dd></div><div :class="ui('$all', '$div')"><dt :class="ui('$all', '$dt')">Recipient</dt><dd :class="ui('$all', '$dd')">{{data.delivery.destination_name}} · {{data.delivery.destination}}</dd></div><div :class="ui('$all', '$div')"><dt :class="ui('$all', '$dt')">Attempts</dt><dd :class="ui('$all', '$dd')">{{data.delivery.attempts}} total · retry cycle {{data.delivery.cycle}} · {{data.delivery.cycle_attempts}} / 5 this cycle</dd></div><div :class="ui('$all', '$div')"><dt :class="ui('$all', '$dt')">{{data.delivery.completed_at?'Completed':'Next eligible'}}</dt><dd :class="ui('$all', '$dd')"><DateTime :class="ui('$all', '$DateTime')" :value="data.delivery.completed_at??data.delivery.eligible_at"/></dd></div><div :class="ui('$all', '$div')"><dt :class="ui('$all', '$dt')">Expiry</dt><dd :class="ui('$all', '$dd')"><DateTime :class="ui('$all', '$DateTime')" :value="data.delivery.expires_at"/></dd></div><div :class="ui('$all', '$div')" v-if="data.delivery.lease_until"><dt :class="ui('$all', '$dt')">Worker lease</dt><dd :class="ui('$all', '$dd')"><DateTime :class="ui('$all', '$DateTime')" :value="data.delivery.lease_until"/></dd></div><div :class="ui('$all', '$div')"><dt :class="ui('$all', '$dt')">Reason</dt><dd :class="ui('$all', '$dd')">{{data.delivery.reason??'No actionable failure recorded'}}</dd></div></dl><div :class="ui('$all', '$div', 'inline-actions')"><button v-if="data.delivery.can_retry" :class="ui('$all', '$button', 'button primary')" :disabled="saving" @click="retry">Retry unchanged delivery</button><button v-if="data.delivery.can_review_resend" :class="ui('$all', '$button', 'button')" :disabled="saving" @click="preview">Review and resend</button><RouterLink v-if="data.delivery.issue_id" :to="{path:'/errors/'+data.delivery.issue_id,query:data.delivery.action.startsWith('github_')?{tab:'links'}:{}}" :class="ui('$all', '$a', 'text-link')">{{data.delivery.action.startsWith('github_')?'Review GitHub reservation':'Open investigation'}}</RouterLink></div><p v-if="data.delivery.action.startsWith('github_')" :class="ui('$all', '$p', 'help')">Ambiguous GitHub creation is held for review, never blindly retried. Review the repository reservation before any new creation.</p><p v-else :class="ui('$all', '$p', 'help')">Retries retain the ID and frozen body. A separately reviewed resend gets a new ID. Notification recovery may duplicate a message after uncertain acceptance.</p></div><section v-if="review" :class="ui('$all', '$section', 'panel reviewed-resend')"><h2 :class="ui('$all', '$h2')">Review a new delivery identity</h2><pre :class="ui('$all', '$pre')">{{review.text}}</pre><p :class="ui('$all', '$p', 'help')">Confirm these newly sanitized bytes. This may duplicate a previously accepted message. Current rule, issue, recipient and actor policy are checked again.</p><div :class="ui('$all', '$div', 'inline-actions')"><button :class="ui('$all', '$button', 'button primary')" :disabled="saving" @click="resend">Confirm reviewed resend</button><button :class="ui('$all', '$button', 'button')" :disabled="saving" @click="review=null">Cancel review</button></div></section><div :class="ui('$all', '$div', 'delivery-detail-grid')"><section :class="ui('$all', '$section', 'panel')"><h2 :class="ui('$all', '$h2')">Payload · {{data.payload_state}}</h2><pre v-if="data.payload_text" :class="ui('$all', '$pre', 'delivery-payload')">{{data.payload_text}}</pre><p :class="ui('$all', '$p')" v-else>The encrypted event or payload could not be read. Review host encryption-key availability.</p><p :class="ui('$all', '$p', 'help')">{{data.payload_state==='preview'?'Not frozen yet; current export policy is applied before its first attempt.':'Frozen logical payload. Later prohibited exports are cancelled instead of rewritten.'}}</p></section><section :class="ui('$all', '$section', 'panel')"><h2 :class="ui('$all', '$h2')">Supporting rules</h2><article :class="ui('$all', '$article')" v-for="r in data.rules" :key="r.id+':'+r.version"><strong :class="ui('$all', '$strong')">{{r.name}}</strong><small :class="ui('$all', '$small')"> revision {{r.version}}</small><pre :class="ui('$all', '$pre')">{{JSON.stringify(r.conditions,null,2)}}</pre></article><p :class="ui('$all', '$p')" v-if="!data.rules.length">{{data.delivery.action.startsWith('report_')?'Report subscription; scheduled delivery or explicit preview. No immediate alert rule required.':data.delivery.action.startsWith('github_')?'Repository reservation; automatic or explicitly reviewed creation.':'Explicit synthetic test; no automatic rule required.'}}</p></section></div><section :class="ui('$all', '$section', 'panel attempts-panel')"><h2 :class="ui('$all', '$h2')">Provider attempts</h2><p :class="ui('$all', '$p', 'help')">Cooldown waits and duplicate jobs do not consume attempts. An expired worker lease can leave acceptance unknown.</p><ol :class="ui('$all', '$ol', 'attempt-list')"><li :class="ui('$all', '$li')" v-for="a in data.attempts" :key="a.sequence"><strong :class="ui('$all', '$strong')">Attempt {{a.sequence}} · cycle {{a.cycle}} · {{a.outcome}}</strong><time :class="ui('$all', '$time')"><DateTime :class="ui('$all', '$DateTime')" :value="a.started_at"/> to <DateTime :class="ui('$all', '$DateTime')" :value="a.completed_at"/></time><p :class="ui('$all', '$p')">{{a.summary}}</p><small :class="ui('$all', '$small')"><span :class="ui('$all', '$span')" v-if="a.status">HTTP {{a.status}} · </span>{{a.code}}<span :class="ui('$all', '$span')" v-if="a.retry_after_at"> · earliest retry <DateTime :class="ui('$all', '$DateTime')" :value="a.retry_after_at"/></span></small></li></ol><p :class="ui('$all', '$p')" v-if="!data.attempts.length">No provider attempt has started.</p></section></template></template>
